content:
:root {
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--card-bg);
  padding: 20px 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

.chart-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.table-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  overflow-x: auto;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background-color: #ffffff;
  color: var(--text-main);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s;
}

.btn:hover {
  background-color: #f1f5f9;
}

.btn-primary {
  background-color: var(--primary);
  color: #ffffff;
  border-color: var(--primary);
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.input {
  width: 100%;
  padding: 8px 12px;
  font-size: 0.875rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s;
}

.input:focus {
  border-color: var(--primary);
}

.flex-row {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.flex-row > * {
  flex: 1;
  min-width: 300px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.875rem;
}

.table th,
.table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-color);
}

.table th {
  font-weight: 600;
  color: var(--text-muted);
  background-color: #f8fafc;
}

.summary-box {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.summary-item {
  background: var(--card-bg);
  padding: 16px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border-left: 4px solid var(--primary);
}

.summary-item .label {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.summary-item .value {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
}

export interface MonthSales {
  month: string;
  sales: number;
}

export interface SalesTableProps {
  data: MonthSales[];
  onUpdate: (month: string, sales: number) => void;
}

export interface SalesChartProps {
  data: MonthSales[];
}

import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import { SalesChartProps } from '../types';

export default function SalesChart({ data = [] }: SalesChartProps) {
  return (
    <div className="chart-card">
      <h3 style={{ fontSize: '1.1rem', fontWeight: 600 }}>月別売上グラフ</h3>
      <div style={{ width: '100%', height: 350 }}>
        <ResponsiveContainer>
          <BarChart data={data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
            <XAxis dataKey="month" stroke="#64748b" fontSize={12} />
            <YAxis stroke="#64748b" fontSize={12} tickFormatter={(value) => `${value.toLocaleString()}万`} />
            <Tooltip 
              formatter={(value: any) => [`${Number(value).toLocaleString()} 万円`, '売上']}
              contentStyle={{ backgroundColor: '#ffffff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
            />
            <Bar dataKey="sales" fill="#4f46e5" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { SalesTableProps } from '../types';

export default function SalesTable({ data = [], onUpdate }: SalesTableProps) {
  const handleChange = (month: string, value: string) => {
    const num = Number(value);
    if (!isNaN(num)) {
      onUpdate?.(month, num);
    }
  };

  return (
    <div className="table-card">
      <h3 style={{ marginBottom: '16px', fontSize: '1.1rem', fontWeight: 600 }}>売上データ編集</h3>
      <table className="table">
        <thead>
          <tr>
            <th>月</th>
            <th>売上 (万円)</th>
          </tr>
        </thead>
        <tbody>
          {data.map((item) => (
            <tr key={item.month}>
              <td style={{ fontWeight: 500 }}>{item.month}</td>
              <td>
                <input
                  type="number"
                  className="input"
                  value={item.sales}
                  onChange={(e) => handleChange(item.month, e.target.value)}
                  min="0"
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useState } from 'react';
import { MonthSales } from './types';
import SalesChart from './components/SalesChart';
import SalesTable from './components/SalesTable';

const initialData: MonthSales[] = [
  { month: '1月', sales: 120 },
  { month: '2月', sales: 140 },
  { month: '3月', sales: 180 },
  { month: '4月', sales: 160 },
  { month: '5月', sales: 210 },
  { month: '6月', sales: 250 },
  { month: '7月', sales: 230 },
  { month: '8月', sales: 190 },
  { month: '9月', sales: 220 },
  { month: '10月', sales: 270 },
  { month: '11月', sales: 300 },
  { month: '12月', sales: 350 },
];

export default function App() {
  const [data, setData] = useState<MonthSales[]>(initialData);

  const handleUpdate = (month: string, sales: number) => {
    setData((prev) =>
      prev.map((item) => (item.month === month ? { ...item, sales } : item))
    );
  };

  const handleReset = () => {
    setData(initialData);
  };

  const totalSales = data.reduce((acc, cur) => acc + cur.sales, 0);
  const averageSales = Math.round(totalSales / (data.length || 1));
  const maxSales = data.length > 0 ? Math.max(...data.map((d) => d.sales)) : 0;
  const maxMonth = data.find((d) => d.sales === maxSales)?.month || '-';

  return (
    <div className="app-container">
      <header className="header">
        <h1>売上管理ダッシュボード（1月〜12月）</h1>
        <button className="btn" onClick={handleReset}>
          初期値に戻す
        </button>
      </header>

      <div className="summary-box">
        <div className="summary-item">
          <div className="label">年間総売上</div>
          <div className="value">{totalSales.toLocaleString()} 万円</div>
        </div>
        <div className="summary-item">
          <div className="label">月平均売上</div>
          <div className="value">{averageSales.toLocaleString()} 万円</div>
        </div>
        <div className="summary-item">
          <div className="label">最高売上月</div>
          <div className="value">{maxMonth} ({maxSales.toLocaleString()}万円)</div>
        </div>
      </div>

      <SalesChart data={data} />

      <div className="flex-row">
        <SalesTable data={data} onUpdate={handleUpdate} />
      </div>
    </div>
  );
}
